contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }
    function testRegression_property() public {
        address token = address(new Token());
        address from = address(0x123);
        address to = address(0x456);
        uint256 amount = 100;

        Token(token).mint(from, amount);
        vm.prank(from);
        Token(token).approve(address(c), amount);

        address[] memory tos = new address[](1);
        tos[0] = to;
        uint256[] memory vals = new uint256[](1);
        vals[0] = amount;
        c.transfer(from, token, tos, vals);

        assertEq(Token(token).balanceOf(to), amount);
    }
}

contract Token {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount);
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
